import{z as B,x as i,o,c as d,q as t,j as l,D as E,d as e,s as n,S as A,b as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"缓存压缩","description":"","frontmatter":{"title":"缓存压缩","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cache-compression.md","filePath":"cs/cache-compression.md","lastUpdated":1791413859000}'),p={name:"cs/cache-compression.md"};function m(c,a,D,C,h,L){const r=i("Mermaid");return o(),d("div",null,[a[2]||(a[2]=t('<h1 id="缓存压缩" tabindex="-1">缓存压缩 <a class="header-anchor" href="#缓存压缩" aria-label="Permalink to &quot;缓存压缩&quot;">​</a></h1><div class="epigraph"><p>许多行的数据是稀疏、重复或窄整数；压缩后同一 SRAM 可以多住几块，代价是命中路径上的编解码与可变行大小。</p><footer>—— 据 Alameldeen and Wood；Pekhimenko et al., Base-Delta-Immediate Compression, PACT 2012 整理</footer></div><p><a href="/cs/cache-partition-qos">上一课</a> 按核切容量。配额仍以物理行为单位，一行 64B 里若只有少量有效信息，配额浪费。本课不重切 way。缺口是<strong>压缩：在填入时把行变短，让一组里塞进多于相联度的「逻辑块」，缺失率下降。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指针、小整数数组、全零行在 LLC 里极常见。不压缩则每块固定 64B。<a href="/cs/mlp-memory-parallelism">MLP</a> 再高也救不了「工作集以块计刚好溢出」。缺口不是再分区，而是<strong>用简单、定界延迟的编码提高有效容量</strong>，且解压必须适合 L2/L3 命中路径。</p><p><span class="marginnote">术语翻译：BDI（基址-差值-立即数）就是「记一个基准值，其余只记差几」——像记全班身高都在 175 上下，每人只写正负几厘米；零块和重复值是它的退化特例。</span></p><p><span class="marginnote">BDI：一行用一个基址加窄的 delta。零块、重复值是更简单的特例。压缩率随数据变，标签阵列要能指向「半行」「四分之一行」的槽。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>填入：试几种编码，选能装进更少子块的方案；失败则不压缩。标签：每块仍有完整 PA 标签 + 压缩模式 + 起始槽。命中：按模式解压再返回。替换：按压缩后占用的槽数计，可能一次踢出「逻辑一块」。</p><p><span class="marginnote">数字实例：一行装 16 个 32 位小整数、数值都在 1000 附近，BDI 取 1000 为基址、每个差值 1 字节：64 B 压成 4+16=20 B，同一组能装下的逻辑块数约为原来的 3 倍。</span></p>',10)),(o(),l(A,null,{default:E(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILL%5B%22%E4%BB%8E%20DRAM%20%E5%A1%AB%E5%85%A5%22%5D%20--%3E%20TRY%5B%22%E5%B0%9D%E8%AF%95%E7%BC%96%E7%A0%81%22%5D%0A%20%20TRY%20--%3E%7C%22%E5%8F%98%E7%9F%AD%22%7C%20SLOT%5B%22%E5%8D%A0%E7%94%A8%E6%9B%B4%E5%B0%91%E6%A7%BD%22%5D%0A%20%20TRY%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%22%7C%20FULL%5B%22%E5%8D%A0%E6%95%B4%E8%A1%8C%22%5D%0A%20%20HIT%5B%22%E5%91%BD%E4%B8%AD%22%5D%20--%3E%20DEC%5B%22%E8%A7%A3%E5%8E%8B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[e("有效容量上升，冲突/容量缺失下降，与 "),s("a",{href:"/cs/rrip-dead-block"},"RRIP"),e(" 叠加。副作用：同一组里块数可变，替换与分区的「路」不再整齐；QoS 记账要从路数改成槽数。命中延迟增加一级组合逻辑，因此 L1 很少压，LLC 更常见。")],-1)),(o(),l(A,null,{default:E(()=>[n(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E4%BC%A0%E7%BB%9F%3A%2016%20%E8%B7%AF%E5%90%84%2064B%22%5D%20--%3E%20ACC%5B%22%E6%8C%89%E8%B7%AF%E4%B8%8E%E5%9D%97%E6%95%B0%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20CMP%5B%22%E5%8E%8B%E7%BC%A9%3A%20%E5%9D%97%E5%8F%AA%E5%8D%A0%E5%AD%90%E6%A7%BD%22%5D%20--%3E%20VAR%5B%22%E5%90%8C%E7%BB%84%E9%80%BB%E8%BE%91%E5%9D%97%E6%95%B0%E5%8F%AF%E5%8F%98%22%5D%0A%20%20VAR%20--%3E%20ACC2%5B%22%E8%AE%B0%E8%B4%A6%E6%94%B9%E6%8C%89%E6%A7%BD%E6%95%B0%22%5D%0A%20%20ACC2%20--%3E%20REPL%5B%22%E6%9B%BF%E6%8D%A2%E4%B8%80%E6%AC%A1%E5%8F%AF%E8%B8%A2%E5%A4%9A%E4%B8%AA%E9%80%BB%E8%BE%91%E5%9D%97%22%5D%0A%20%20ACC2%20--%3E%20QOS%5B%22%E5%88%86%E5%8C%BA%E9%85%8D%E9%A2%9D%E4%B9%9F%E6%8C%89%E6%A7%BD%E8%AE%A1%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">常见误区：初学者容易以为压缩总赚——命中路径多一级解压组合逻辑，L1 减不得这点延迟；随机数据还压不动、白费一次编码尝试。所以压缩几乎只出现在 LLC。</span></p><p>一致性仍按物理行：压缩是私有表示，总线/目录上看完整 64B 或按扇区，下一课扇区会碰到部分行。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把通用压缩算法（LZ）放进命中路径。也不把 GPU 的帧缓冲压缩当 CPU LLC 的同一实现。近存计算会把「不搬数据」当作另一种减带宽，那是很后面的课。行大小本身（32/64/128B）与扇区是下一课的几何。</p><p>后课默认：LLC 可以用简单编码提高有效块数。未压缩时，行大小与是否按扇区填，仍决定假共享与带宽。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>简单数据编码提高 LLC 有效容量，解压加在命中路径。</li><li>可变槽让分区与替换的记账变复杂。</li><li>行大小与扇区缓存是下一课几何问题。</li><li>出处：Alameldeen and Wood；Pekhimenko et al., <em>PACT</em>, 2012。</li></ul>',7))])}const u=B(p,[["render",m]]);export{f as __pageData,u as default};
